\end{equation}

\label{def:key-state}
A conference key state $\gamma^c_{\vv{K}E}$, with $|K_i|=K$ for all $i\in[M]\coloneqq\{1,…,M\}$, is defined as 
\begin{align}
& \mathcal{D}_{K_1}\otimes\mathcal{D}_{K_2}\otimes\cdots\otimes \mathcal{D}_{K_M}\left(\gamma^c_{\vv{K} E}\right) \coloneqq \nonumber \\ 
&\qquad \frac{1}{K}\sum_{k\in\msc{K}}\op{k}_{K_1}\otimes \op{k}_{K_2}\otimes\cdots \otimes \op{k}_{K_M}\otimes\sigma_E, \label{eq:key-state}
\end{align}
where $\sigma_E$ is a state of the system $E$, which is accessible to an eavesdropper Eve, $\mathcal{D}(\cdot)=\sum_{k\in\msc{K}}\op{k}(\cdot)\op{k}$ is a projective measurement channel, $\{\ket{k}_{K_i}\}_{k\in\msc{K}}$ forms an orthonormal basis for each $i\in[M]$.

A state $\rho_{\vv{K}E}$ is called an $\varepsilon$-approximate conference key state, for $\varepsilon\in[0,1]$, if there exists a conference key state $\gamma^c_{\vv{K} E}$ such that~\cite{AH09}
\begin{equation}
F\(\gamma^c_{\vv{K} E},\rho_{\vv{K}E}\)\geq 1-\varepsilon.

\label{def:multi-priv-state}
A state $\gamma_{\vv{SM}}$, with $|K_i|=K$ for all $i\in[M]$ is called a ($M$-partite) private state if and only if 
\begin{equation}\label{eq:multi-priv-state}
\gamma_{\vv{SK}}\coloneqq U^{\text{tw}}_{\vv{SK}} (\Phi^{\operatorname{GHZ}}_{\vv{K}}\otimes\omega_{\vv{S}}) (U^{\text{tw}}_{\vv{SK}})^\dag,
\end{equation}
where $U^{\text{tw}}_{\vv{SK}}\coloneqq \sum_{\vv{k}\in\msc{K}^{\times M}}\op{\vv{k}}_{\vv{K}}\otimes U^{\vv{k}}_{\vv{S}}$ is called a twisting unitary operator for some unitary operator $U^{\vv{k}}_{\vv{S}}$ and $\omega$ is some density operator~\cite{AH09}.

\label{def:gen-div-ent}
The generalized divergence of entanglement $\tf{E}_{\text{E}}$ or genuine mulipartite entanglement (GME) $\tf{E}_\text{GE}$ of an arbitrary state $\rho_{\vv{A}}$ is defined as~\cite{CPV19}
\begin{equation}\label{eq:def-gen-ent}
\tf{E}_{r}(:\!\vv{A}\!:)_{\rho}\coloneqq \inf_{\sigma\in\tf{F}(:\!\vv{A}\!:)}\tf{D}(\rho_{\vv{A}}\Vert\sigma_{\vv{A}}),
\end{equation} 
when $\tf{F}=\operatorname{FS}$ or $\tf{F}=\operatorname{BS}$ for $r=\text{E}$ or $r=\text{GE}$, respectively, where $\tf{D}(\rho\Vert\sigma)$ denotes the generalized divergence.

Entangling power of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with respect to entanglement measure $\tf{E}_{r}$ [Eq. ~\eqref{eq:def-gen-ent}] is defined as the maximum possible gain in the entanglement $\tf{E}_r$ when a quantum state when acted upon by the given channel $\mc{N}$, 
\begin{align}
&\tf{E}_{r}^{p}(\mc{N})\coloneqq\nonumber\\
&\qquad \sup_{\rho}\left[\tf{E}_{r}(:\!\vv{LA}\!:\!\vv{R}\!:\!\vv{PC}\!:)_{\mc{N}(\rho)} -\tf{E}_{r}(:\!\vv{LA'}\!:\!\vv{RB}\!:\!\vv{P}\!:)_{\rho}\right],
\end{align}
where optimization is over all possible input states $\rho_{\vv{LA'}\vv{RB}\vv{P}}$.

\label{lem:max-amor}
The entangling power of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with respect to the max-relative entropy of entanglement $E_{\max,\operatorname{E}}$ is equal to the max-relative entropy of entanglement of the channel $\mc{N}$,
\begin{equation}
E_{\max,E}^{p}(\mc{N})=E_{\max,E}(\mc{N}).\label{eq:max-amor}
\end{equation}

\label{lem:ree-amor}
For finite dimensional Hilbert spaces the entangling power of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with respect to the relative entropy of entanglement $E_{E}$ is less than or equal to the regularized relative entropy of entanglement of the channel $\mc{N}$,
\begin{equation}
E_{E}^{p}(\mc{N})\leq E^\infty_{E}(\mc{N}).
\end{equation}

Let $\rho_{\vv{LA'}\vv{RB}\vv{P}}$ be a state and let $\sigma'\in\operatorname{FS}(:\vv{LA'}:\vv{RB}:\vv{P}:)$. Let $\Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ an LOCC channel. Then the following inequality holds
\begin{multline}
E_{E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\ 
 \leq D\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \).
 \end{multline}
Applying the the chain rule from Ref.~\cite{fang2019chain}, we find that
\begin{align*}
&D\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \)\\
\leq&D\(\rho_{\vv{LA'}\vv{RB}\vv{P}}\Vert \sigma'_{\vv{LA'}\vv{RB}\vv{P}} \)\\ 
& +D^{\infty}\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\).
\end{align*}
Since the above holds for arbitrary fully separable states $\sigma'_{\vv{LA'}\vv{RB}\vv{P}}$ and arbitrary LOCC channels $\Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$, we arrive at
\begin{multline}
E_{E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\
 \leq  E_{E}(:\vv{LA'}:\vv{RB}:\vv{P}:)_{\rho}+ E^\infty_{E}(\mc{N}),
\end{multline}
finishing the proof.

\label{thm:priv-test}
If a state $\rho_{\vv{SK}}$ is $\varepsilon$-approximate to $\gamma_{\vv{SK}}$, i.e., $F(\rho_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon$ then $\rho_{\vv{KS}}$ passes $\gamma$-privacy test with success probability $ 1-\varepsilon$, i.e., 
\begin{equation}
\operatorname{Tr}[\Pi^{\gamma}_{\vv{SK}}\rho_{\vv{SK}}] \geq 1-\varepsilon.
\end{equation}

\label{thm:priv-gme}
A biseparable state $\sigma_{\vv{SK}}\in\operatorname{BS}(:\!\vv{SK}\!:)$ can never pass any $\gamma$-privacy test with probability greater $1/K$, i.e.,
\begin{align}
    \operatorname{Tr}[\Pi^{\gamma}_{\vv{SK}}\sigma_{\vv{SK}}]\leq \frac{1}{K}.
\end{align}

The following inequality is a direct consequence of the definitions: 
\begin{equation}
\hat{P}_{\operatorname{LOCC}}(\mc{N})\leq \widetilde{P}_{\operatorname{LOCC}}(\mc{N}).
\end{equation}

\label{thm:one-shot-cppp}
For any fixed $\varepsilon\in(0,1)$, the achievable region of cppp-assisted secret key agreement over a single use of multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ satisfies 
\begin{equation}\label{eq:one-shot-cppp}
\hat{P}_{\textnormal{cppp}}^{\mc{N}}(1,\varepsilon)\leq E^\varepsilon_{h,\operatorname{GE}}(\mc{N}),
\end{equation} 
where 
\begin{equation}
E^{\varepsilon}_{h,\operatorname{GE}}(\mc{N})  \coloneqq \sup_{\psi\in\operatorname{FS}(:\vv{LA'}:\vv{RB}:)}\inf_{\sigma\in\operatorname{BS}(:\vv{LA}:\vv{R}:\vv{C}:)} D^\varepsilon_h(\mc{N}(\psi)\Vert\sigma)
\end{equation}
is the $\varepsilon$-hypothesis testing relative entropy of genuine entanglement of the multiplex channel $\mc{N}$. It suffices to optimize over pure input states $\psi\in\operatorname{FS}(:\!\vv{LA'}\!:\!\vv{RB}\!:)$.

A weak converse bound on the cppp-assisted secret-key-agreement capacity of a multiplex channel $\mc{N}$ is given by
\begin{align}
    \hat{P}_{\textnormal{cppp}}(\mc{N})& = \inf_{\varepsilon\in (0,1)}\liminf_{n\to\infty}\hat{P}^{\mc{N}}_{\textnormal{cppp}}(n,\varepsilon)\\ 
    &\leq E^{\infty}_{\operatorname{GE}}(\mc{N}).
\end{align}

\label{thm:emax-key-converse} For a fixed $n,\ K\in\mathbb{N},\ \varepsilon\in(0,1)$, the following bound holds for an $(n,K,\varepsilon)$ protocol for LOCC-assisted secret key agreement over a multiplex $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$: 
\begin{equation}\label{eq:emax-key-converse} 
\frac{1}{n}\log_2K\leq E_{\max,E}(\mc{N})+ \frac{1}{n}\log_2\left(\frac{1}{1-\varepsilon}\right), 
\end{equation} 
where the max-relative entropy of entanglement $E_{\max,\operatorname{E}}(\mc{N})$ of the multiplex channel $\mc{N}$ is 
\begin{equation*} 
E_{\max,\operatorname{E}}(\mc{N}) \coloneqq \sup_{\psi\in\operatorname{FS}(:\vv{LA'}:\vv{RB}:)}\inf_{\sigma\in\operatorname{FS}(:\vv{LA}:\vv{R}:\vv{C}:)} D_{\max}(\mc{N}(\psi)\Vert\sigma)
\end{equation*} 
and it suffices to optimize over pure states $\psi$.

The bound in \eqref{eq:emax-key-converse} can also be rewritten as 
\begin{equation}
1-\varepsilon \leq 2^{-n (P-E_{\max,\operatorname{E}}(\mc{N}))},
\end{equation}
where we have $P=\frac{1}{n}\log_2 K$. Thus, if the secret-key-agreement rate $P$ is strictly greater than the max-relative entropy of entanglement $E_{\max,\operatorname{E}}(\mc{N})$ of the (multiplex) channel $\mc{N}$, then the fidelity of the distillation $(1-\varepsilon)$ decays exponentially fast to zero in the number of channel uses.

The strong converse LOCC-assisted secret-key-agreement capacity of a multiplex channel $\mc{N}$ is bounded from above by its max-relative entropy of entanglement:
\begin{equation}
\wt{P}_{\operatorname{LOCC}}(\mc{N})\leq E_{\max,E}(\mc{N}).
\end{equation}

\label{thm:ree-key-converse}  
For finite Hilbert space dimensions the asymptotic LOCC-assisted secret-key-agreement capacity of a  multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ is bounded by its regularized relative entropy of entanglement:
\begin{equation}\label{eq:ree-key-converse} 
\widetilde{\mc{P}}_{\operatorname{LOCC}}(\mc{N})\leq E_{E}^\infty(\mc{N}).
\end{equation}

A multipartite quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ is teleportation-simulable with associated resource state $\theta_{\vv{LA}\vv{R}\vv{C}}$, where $R_b\simeq B_b$ for all $b\in\msc{B}$ and $L_a\simeq A'_a$ for all $a\in\msc{A}$, if for all input states $\rho_{\vv{A'}\vv{B}}$ the following identity holds
\begin{equation}\label{eq:tele-sim}
\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{A'}\vv{B}})=\mc{T}_{\vv{A'LA}\vv{BR}\vv{C}\to\vv{A}\vv{C}}(\rho_{\vv{A'}\vv{B}}\otimes\theta_{\vv{LA}\vv{R}\vv{C}})

\end{equation} 
for some LOCC channel $\mc{T}$ with input partition $:\vv{A'LA}:\vv{BR}:\vv{C}:$ and output partition $:\vv{A}:\vv{C}:$.

A multiplex quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ is \textit{covariant} with respect to these representations if the following relation holds for all input states $\rho_{\vv{A'}\vv{B}}$ and group elements $g_a\in\msc{G}_a$ and $g_b\in\msc{G}_b$ for all $a\in\msc{A}$ and $b\in\msc{B}$: 
\begin{align}
&\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\(\(\bigotimes_{a\in\msc{A}}\mathcal{U}_{A'_a}^{g_a}\otimes\bigotimes_{b\in\msc{B}}\mathcal{U}_{B_b}^{g_b}\)(\rho_{\vv{A'}\vv{B}})\)\nonumber\\
&=\(\bigotimes_{a\in\msc{A}}\mathcal{W}_{A_a}^{\vv{g}}\otimes\bigotimes_{c\in\msc{C}}\mathcal{W}_{C_c}^{\vv{g}}\)\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{A'}\vv{B}})\),
\end{align}
where we have used the notation $\mc{U}(\cdot)\coloneqq U(\cdot)U^{\dag}$ for unitaries $U$.

\label{rem:comp}
Tele-covariance of a channel is with respect to the groups and their unitary representations on the input and output Hilbert spaces of the channel. If associated unitary representations for the tele-covariant channels $\mc{N}^1$ and $\mc{N}^2$ are respectively same on the output Hilbert spaces of $\mc{N}^1$ that are also the input Hilbert spaces for $\mc{N}^2$, then the composition channel $\mc{N}=\mc{N}^2\circ\mc{N}^1$ is also tele-covariant. 

A quantum channel obtained by the tensor-product (super-operation ``~$\otimes$", which physically means parallel uses) of tele-covariant channels is also a tele-covariant channel.

\label{thm:bicov}
If a multipartite channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$
is tele-covariant, then it is teleportation-simulable with resource state~\eqref{eq:tele-sim} as its Choi state, i.e., $\theta_{\vv{LA}\vv{R}\vv{C}}=\mc{N}(\Phi^+_{\vv{L}\vv{R}|\vv{A'}\vv{B}})$.

\label{theo:telecov-weakconv-GE}
The LOCC-assisted secret-key-agreement capacity of a multiplex quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ which is teleportation-simulable with resource state $\theta_{\vv{LA}\vv{R}\vv{C}}$ is upper bounded as 
\begin{equation}
\hat{P}_{\operatorname{LOCC}}(\mc{N})\leq E^{\infty}_{GE}(:\vv{LA}:\vv{R}:\vv{C}:)_{\theta}, 
\end{equation}
where $E^\infty(:\vv{A}:)_{\rho}$ is the regularized relative entropy of entanglement of state $\rho_{\vv{A}}$.

\label{theo:E-alpha_bound}
For a fixed $n,\ K\in\mathbb{N},\ \varepsilon\in(0,1)$, the following bound holds for an $(n,M,\varepsilon)$ protocol for LOCC-assisted secret key agreement over a multiplex teleportation-simulable quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with associated resource state $\theta_{\vv{LA}\vv{R}\vv{C}}$,  $\forall \alpha>1$,
\begin{equation}\label{eq:GE-tele-weak-converse}
\frac{1}{n} \log_2 K \leq  \widetilde{E}_{\alpha,E} (:\vv{LA}:\vv{R}:\vv{C}:)_{\theta} 
+\frac{\alpha}{n(\alpha-1)}\log_2 \!\(
