\end{align}
with $\Omega = (1-\varepsilon)\rho$.

We begin by showing the bound for pure biseparable states $\ket{\varphi}_{\vv{KS}}$. For such a state there exists a bipartition of the parties, defined by nonempty index sets $I\subset\{1,...,M\}$ and $J=\{1,...,M\}\setminus I$, such that the state is product with respect to that bipartition.  Namely $\ket{\varphi}_{\vv{KS}}=\ket{\widetilde\varphi}_{S_{I}K_{I}}\otimes\ket{\overline\varphi}_{S_{J}K_{J}}$, where we have defined $\mc{H}_{S_{I}K_{I}}=\bigotimes_{i\in I}\mc{H}_{S_{i}K_{i}}$ and $\mc{H}_{S_{J}K_{J}}=\bigotimes_{j\in J}\mc{H}_{S_{j}K_{j}}$.
Let us also define $m:=|I|$ and $n:=|J|$ and note that $M=m+n$. We can expand
\begin{align}
&\ket{\widetilde\varphi}_{S_{I}K_{I}}=\sum_{i_1,...,i_{m}=0}^{K-1}\widetilde{\alpha}_{i_1...i_{m}}\ket{i_1...i_{m}}_{K_{I}}\otimes\ket{\widetilde{\phi}_{i_1...i_{m}}}_{S_{I}}\\
&\ket{\overline\varphi}_{S_{J}K_{J}}=\sum_{j_1,...,j_{n}=0}^{K-1}\overline{\alpha}_{j_1...j_{n}}\ket{j_1...j_{n}}_{K_J}\otimes\ket{\overline{\phi}_{j_1...j_{n}}}_{S_J}.
\end{align}
Here $\widetilde{\alpha}_{i_1...i_{m}}\in\bbm{C}$ such that $\sum_{i_1,...,i_{m}=0}^{K-1}|\widetilde{\alpha}_{i_1...i_{m}}|^2=1$ and $\overline{\alpha}_{j_1...j_{n}}\in\bbm{C}$ such that $\sum_{j_1,...,j_{n}=0}^{K-1}|\overline{\alpha}_{j_1...j_{n}}|^2=1$. Further it holds

\begin{widetext}
\begin{align}
\operatorname{Tr}\left[\Pi^{\gamma,K}_{\vv{KS}}\varphi_{\vv{KS}}\right]
&=\operatorname{Tr}\left[\(\frac{1}{K}\sum_{i,k=0}^{K-1}\(\ket{i}\bra{k}\)^{\otimes M}_{\vv{K}}\otimes U_{\vv{S}}^{(i^M)}U_{\vv{S}}^{(k^M)\dag}\)\widetilde\varphi_{K_IS_I}\otimes\overline\varphi_{K_JS_J}\right]\\
&=\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^{m}}\overline{\alpha}_{i^{n}}(\widetilde{\alpha}_{k^{m}})^*(\overline{\alpha}_{k^{n}})^*\operatorname{Tr}\left[U^{(i^M)\dag}\ket{\widetilde{\phi}_{i^m}}\bra{\widetilde{\phi}_{k^m}}_{S_I}\otimes\ket{\overline{\phi}_{i^n}}\bra{\overline{\phi}_{k^n}}_{S_J}U^{(k^M)}\right]\\
&=\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^m}\overline{\alpha}_{i^n}(\widetilde{\alpha}_{k^m})^*(\overline{\alpha}_{k^n})^*\bra{\zeta_k}\ket{\zeta_i},\label{eq:9}
\end{align}
\end{widetext}
where we have defined the state
\begin{equation}
\ket{\zeta_i}_{\vv{S}} \coloneqq U^{(i^M)\dag}\ket{\widetilde{\phi}_{i^m}}_{S_I}\otimes\ket{\overline{\phi}_{i^n}}_{S_J}.
\end{equation}
We note that eq. (\ref{eq:9}) is a probability, in particular it is real and non-negative. Hence it holds
\begin{align}
&\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^m}\overline{\alpha}_{i^n}(\widetilde{\alpha}_{k^m})^*(\overline{\alpha}_{k^n})^*\bra{\zeta_k}\ket{\zeta_i}\\
&=\left|\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^m}\overline{\alpha}_{i^n}(\widetilde{\alpha}_{k^m})^*(\overline{\alpha}_{k^n})^*\bra{\zeta_k}\ket{\zeta_i}\right|\\
&\leq\frac{1}{K}\sum_{i,k=0}^{K-1}\left|\widetilde{\alpha}_{i^m}\right|\left|\overline{\alpha}_{i^n}\right|\left|\widetilde{\alpha}_{k^m}\right|\left|\overline{\alpha}_{k^n}\right|\left|\bra{\zeta_k}\ket{\zeta_i}\right|
\end{align}
where in the first inequality we have used the subadditivity and multiplicity of the absolute value of complex numbers. We note that for all $i,k$ in the sum $\left|\bra{\zeta_k}\ket{\zeta_i}\right|\leq 1$. Let us define $p_i=\left|\widetilde{\alpha}_{i^m}\right|^2$ and note that $p_i\geq0$ and $\sum_{i=0}^{K-1}p_i\leq1$. Let us also define $q_i=\left|\overline{\alpha}_{i^n}\right|^2$ and note that $q_i\geq0$ and $\sum_{i=0}^{K-1}q_i\leq1$. Hence there exist respective probability distributions $\{\hat{p}_i\}$ and $\{\hat{q}_i\}$ over $\{0,...,K-1\}$ such that $p_i\leq\hat{p}_i$ and $q_i\leq\hat{q}_i$ for all $i=0,...,K-1$. We then obtain
\begin{align}
&\frac{1}{K}\sum_{i,k=0}^{K-1}\left|\widetilde{\alpha}_{i^m}\right|\left|\overline{\alpha}_{i^n}\right|\left|\widetilde{\alpha}_{k^m}\right|\left|\overline{\alpha}_{k^n}\right|\left|\bra{\zeta_k}\ket{\zeta_i}\right|\\
&\leq\frac{1}{K}\sum_{i,k=0}^{K-1}\sqrt{p_iq_ip_kq_k} =\frac{1}{K}\left[\sum_{i=0}^{K-1}\sqrt{p_iq_i}\right]^2\\
&\leq\frac{1}{K}\left[\sum_{i=0}^{K-1}\sqrt{\hat{p}_i\hat{q}_i}\right]^2\leq\frac{1}{K},
\end{align}
where we have used that the classical fidelity between two probability distributions is upper bounded by $1$. This establishes the theorem for pure biseparable states with respect to arbitrary bipartitions. Noting that every mixed biseparable state $\sigma_{\vv{KS}}\in\operatorname{BS}(:\vv{KS}:)$ can be expressed as a convex sum of pure biseparable states finishes the proof.

Let us consider any cppp-assisted protocol that achieves a rate $\hat{P}_{\textnormal{cppp}}^{\mc{N}}\equiv \hat{P}$. Let $\rho^{(1)}\in\operatorname{FS}(:\!\vv{LA'}\!:\!\vv{RB}\!:\!\vv{P}\!:)$ be a fully separable state generated by the first use of LOCC among all spatially separated allies. Let 
\begin{equation}
\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}\coloneqq \mc{N}(\rho^{(1)}_{\vv{LA}\vv{RB}\vv{P}}).
\end{equation}  
We note that $\tau^{(1)}$ is a separable state with respect to bipartition $\vv{LA}\vv{R}\vv{C}\!:\!\vv{P}$. The action of the decoder channel $\mc{D}\coloneqq \mc{L}^{(2)}_{\vv{LA}\vv{R}\vv{PC}\to \vv{SK}}$ on $\tau^{(1)}$ yields the state
\begin{equation}
\omega_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}).
\end{equation}
By assumption we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some ($M$-partite) private state $\gamma$. This implies that there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}
From Theorem~\ref{thm:priv-gme},
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\sigma'_{\vv{SK}}]\leq \frac{1}{K}=2^{-\hat{P}},
\end{equation}
for any $\sigma'\in\operatorname{BS}(:\!\vv{SK}\!:)$. 

Let us suppose a state $\sigma_{\vv{LA}\vv{R}\vv{PC}}\in\operatorname{BS}(:\vv{LA}:\vv{R}:\vv{PC}:)$ of the form $\sigma_{\vv{LA}\vv{R}\vv{PC}}=\sigma_{\vv{LA}\vv{R}\vv{C}}\otimes\sigma_{\vv{P}}$, where $\sigma{\vv{LA}\vv{R}\vv{C}}$ is arbitrary. It holds that $\sigma_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\sigma_{\vv{LA}\vv{R}\vv{PC}})\in\operatorname{BS}(:\vv{SK}:)$. Thus, the privacy test is feasible for $D^\varepsilon_h(\omega\Vert \sigma)$ and we find that
\begin{align}
\hat{P} &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert \sigma_{\vv{SK}})\\
&\leq  D^\varepsilon_h(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}} )\label{eq:40}\\
&\leq \sup_{\psi\in\operatorname{FS}(\vv{LA'}:\vv{RB}:\vv{P})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}:\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}})\\
&= \sup_{\psi\in\operatorname{FS}(\vv{LA'}:\vv{RB})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}})\Vert \sigma_{\vv{LA}\vv{R}\vv{C}}).\label{eq:one-shot-proof-part}
\end{align}

The second inequality follows from data processing inequality. The third inequality follows from the quasi-convexity of $D^\varepsilon_h$. The equality follows from Eq.~\eqref{eq:gen-div-prod} and suitable choice of $\sigma_{\vv{P}}$ that always exists because for any pure state $\psi\in\operatorname{FS}(\vv{LA'}:\vv{RB}:\vv{P})$, the output state $\mc{N}(\psi)$ is separable with respect to bipartition $\vv{LA}\vv{R}\vv{C}:\vv{P}$. 

Since inequality \eqref{eq:one-shot-proof-part} also holds for an arbitrary $\sigma\in\operatorname{BS}(:\!\vv{LA}\!:\!\vv{R}\!:\vv{C}\!:)$, we can conclude that
\begin{equation}
\hat{P}\leq E^\varepsilon_{h,\operatorname{GE}}(\mc{N}).
\end{equation}

The following inequality holds for an $(n,K,\varepsilon)$ LOCC-assisted secret key agreement protocol over a multiplex channel $\mc{N}$:
\begin{equation}\label{eq:fid-conv-proof}
F(\omega_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon. 
\end{equation}
For any $\sigma_{\vv{SK}}\in\operatorname{FS}(:\vv{SK}:)$, we have following bound due to inequality \eqref{eq:fid-conv-proof} and Theorem~\ref{thm:priv-gme}:
\begin{equation}
\log_2 K\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}). 
\end{equation}
Employing inequality \eqref{eq:hyp-sand-rel} in the limit $\alpha\to+\infty$, we obtain
\begin{align}
\log_2 K &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}) \\
&\leq D_{\max}(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{align}
Above inequality holds for arbitrary $\sigma\in\operatorname{FS}(:\vv{SK}:)$, therefore
\begin{equation}\label{eq:con-max-proof}
\log_2 K \leq E_{\max,\operatorname{E}}(:\vv{SK}:)_{\omega}+\log_2\left(\frac{1}{1-\varepsilon}\right),
\end{equation}
where $E_{\max,\operatorname{E}}(:\vv{SK}:)_{\omega}$ is the max-relative entropy of entanglement of the state $\omega_{\vv{SK}}$.

The max-relative entropy of entanglement $E_{\max,\operatorname{E}}$ of a state is monotonically non-increasing under the action of LOCC channels and it is zero for states that are fully separable. Using these facts, we get that
\begin{align}
& E_{\max,\operatorname{E}}(:\vv{SK}:)_{\omega}\nonumber \\
&\leq E_{\max,\operatorname{E}}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \label{eq:52}\\
&=  E_{\max,\operatorname{E}}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\
&\qquad - E_{\max,\operatorname{E}}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_1}\\ 
&=E_{\max,\operatorname{E}}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\ 
&\qquad +\left[\sum_{i=2}^n E_{\max,\operatorname{E}}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right.\nonumber \\
&\qquad  -\left. \sum_{i=2}^n E_{\max,\operatorname{E}}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\nonumber \\
&\qquad - E_{\max,\operatorname{E}}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}\\
& \leq \sum_{i=1}^n \left[ E_{\max,\operatorname{E}}(:\vv{L^{(i)}A^{(i)}}:\vv{R^{(i)}}:\vv{P^{(i)}C^{(i)}}:)_{\tau_{i}} \right. \nonumber\\
&\qquad -\left.  E_{\max,\operatorname{E}}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\\
&\leq n E_{\max,\operatorname{E}}(\mc{N}).\label{eq:amor-proof}
\end{align}
The first equality follows because $E_{\max,\operatorname{E}}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}=0$. The second inequality follows because $E_{\max,\operatorname{GE}}$ is monotone under LOCC channels and $\rho_{i}=\mc{L}^{i}(\tau_{i-1})$ for all $i\in\{2,3,\ldots,n\}$. The final inequality follows from Lemma~\ref{lem:max-amor}.

From inequalities \eqref{eq:con-max-proof} and \eqref{eq:amor-proof}, we conclude that
\begin{equation}
\log_2K\leq nE_{\max,\operatorname{E}}(\mc{N})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{equation}

\label{app:ree-key-converse}
For an $(n,K,\varepsilon)$ LOCC-assisted secret key agreement protocol over a multiplex channel $\mc{N}$, such that $F(\omega_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon$, due to inequality \eqref{eq:fid-conv-proof} and Theorem~\ref{thm:priv-gme} it holds for any $\sigma_{\vv{SK}}\in\operatorname{FS}(:\vv{SK}:)$:
\begin{equation}\label{eq:68}
\log_2 K\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}). 
\end{equation}
Using the fact that~\cite{WR12}
\begin{equation}
D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}) \leq \frac{1}{1-\varepsilon}\(D(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}})+h(\varepsilon)\),
\end{equation}
where $h$ is the binary entropy function, and that the bound~\eqref{eq:68} holds for arbitrary $\sigma\in\operatorname{FS}(:\vv{SK}:)$, we obtain
\begin{equation}\label{eq:con-ree-proof-1}
\log_2 K \leq \frac{1}{1-\varepsilon}\(E_{\operatorname{E}}(:\vv{SK}:)_{\omega}+h(\varepsilon)\)\end{equation}
As the relative entropy of entanglement of a state is monotonically non-increasing under the action of LOCC channels and vanishes for states that are fully separable we can repeat the argument in inequalities~\eqref{eq:52}--\eqref{eq:amor-proof} and obtain
\begin{equation}\label{eq:amor-proof_ree}
E_{\operatorname{E}}(:\vv{SK}:)_{\omega}\leq n E^p_{\operatorname{E}}(\mc{N})\leq n E^\infty_{\operatorname{E}}(\mc{N}),
\end{equation}
where the second inequality follows from Lemma~\ref{lem:ree-amor}, Taking the limits $\varepsilon\to0$ and $n\to\infty$, we obtain \begin{equation}
\hat{\mc{P}}_{\operatorname{LOCC}}(\mc{N})\leq E^\infty_{\operatorname{E}}(\mc{N}),
\end{equation}
showing the converse. As for the strong converse, we follow the argument used in Ref.~\cite{WTB16}: From inequalities~\eqref{eq:68} and  \eqref{eq:hyp-sand-rel} we obtain
\begin{equation}\label{eq:con-ree-proof}
\log_2 K \leq \widetilde{E}_{\alpha,\operatorname{E}}(:\vv{SK}:)_{\omega}+\frac{\alpha}{\alpha-1}\log_2\left(\frac{1}{1-\varepsilon}\right),
\end{equation}
where $\alpha\in(1,\infty)$ and $\widetilde{E}_{\alpha,\operatorname{E}}(:\vv{SK}:)_{\omega}$ is the sandwiched R\'{e}nyi relative entropy of entanglement of the state $\omega_{\vv{SK}}$. Rewriting inequality~\eqref{eq:con-ree-proof} we obtain
\begin{equation}
\varepsilon\geq 1- 2^{-n\(\frac{\alpha-1}{\alpha}\)\(\frac{\log_2 K}{n}-\frac{1}{n}\widetilde{E}_{\alpha,\operatorname{E}}(:\vv{SK}:)_{\omega}\)}.
\end{equation}
Assuming that the rate $\frac{\log_2 K}{n}$ exceeds $E_{E}^\infty(\mc{N})$, by inequality~\eqref{eq:amor-proof_ree} it will be larger than $\frac{1}{n}E_{\operatorname{E}}(:\vv{SK}:)_{\omega}$. Hence, there exists an $\alpha>1$, such that $\frac{\log_2 K}{n}-\frac{1}{n}\widetilde{E}_{\alpha,\operatorname{E}}(:\vv{SK}:)_{\omega}>0$ and the error increases to $1$ exponentially.

